import{_ as a,o as s,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"51. 从源代码到可执行文件：编译管道","description":"The Little Book of C 中文版 — 51. 从源代码到可执行文件：编译管道","frontmatter":{"title":"51. 从源代码到可执行文件：编译管道","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","06-编译与构建","中文"],"description":"The Little Book of C 中文版 — 51. 从源代码到可执行文件：编译管道","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":"51","sidebarWeight":"51","alternateZh":"/posts/c教程/zh-CN/06-编译与构建/051-From Source to Executable The Compilation Pipeline","alternateEn":"/posts/c教程/en-US/06-Compilation and Build/051-From Source to Executable The Compilation Pipeline"},"headers":[],"relativePath":"posts/c教程/zh-CN/06-编译与构建/051-From Source to Executable The Compilation Pipeline.md","filePath":"posts/c教程/zh-CN/06-编译与构建/051-From Source to Executable The Compilation Pipeline.md","lastUpdated":1790163617000}'),p={name:"posts/c教程/zh-CN/06-编译与构建/051-From Source to Executable The Compilation Pipeline.md"};function o(l,e,i,c,d,h){return s(),n("div",null,[...e[0]||(e[0]=[t(`<p>[English version](/posts/c教程/en-US/06-Compilation and Build/051-From Source to Executable The Compilation Pipeline)</p><p>每次你跑步的时候</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc hello.c -o hello</span></span></code></pre></div><p>您正在启动一个复杂的多阶段过程，将人类可读的 C 代码转换为机器可执行的二进制文件。了解这个编译管道是成为真正的系统程序员的核心。</p><p>让我们来解开你们之间发生的事情<code>.c</code>文件和最终的可执行文件。</p><h4 id="步骤-1-四个阶段" tabindex="-1">步骤 1. 四个阶段 <a class="header-anchor" href="#步骤-1-四个阶段" aria-label="Permalink to &quot;步骤 1. 四个阶段&quot;">​</a></h4><p>C 编译器（例如<code>gcc</code>或者<code>clang</code>）在内部执行四个主要阶段：</p><table tabindex="0"><thead><tr><th>舞台</th><th>工具</th><th>输入</th><th>输出</th><th>描述</th></tr></thead><tbody><tr><td>1. 预处理</td><td><code>cpp</code></td><td><code>hello.c</code></td><td>扩展源</td><td>手柄<code>#include</code>,<code>#define</code>、 和宏</td></tr><tr><td>2. 编译</td><td><code>cc1</code></td><td>扩展源</td><td><code>hello.s</code></td><td>将 C 翻译成汇编</td></tr><tr><td>3. 组装</td><td><code>as</code></td><td><code>hello.s</code></td><td><code>hello.o</code></td><td>将汇编代码转换为机器代码</td></tr><tr><td>4. 链接</td><td><code>ld</code></td><td><code>.o</code>+ 图书馆</td><td><code>hello</code></td><td>将所有内容组合成一个可运行的程序</td></tr></tbody></table><p>您可以使用编译器标志在任何步骤停止以查看发生了什么。</p><h4 id="小代码-观察每个阶段" tabindex="-1">小代码：观察每个阶段 <a class="header-anchor" href="#小代码-观察每个阶段" aria-label="Permalink to &quot;小代码：观察每个阶段&quot;">​</a></h4><p>让我们使用一个简单的程序：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// hello.c</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Hello, C!\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>运行这些命令来检查每个阶段：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 1. Preprocessing</span></span>
<span class="line"><span>gcc -E hello.c -o hello.i</span></span>
<span class="line"><span># 2. Compilation to Assembly</span></span>
<span class="line"><span>gcc -S hello.i -o hello.s</span></span>
<span class="line"><span># 3. Assembly to Object File</span></span>
<span class="line"><span>gcc -c hello.s -o hello.o</span></span>
<span class="line"><span># 4. Linking</span></span>
<span class="line"><span>gcc hello.o -o hello</span></span></code></pre></div><p>现在检查每个文件的样子：</p><p>-<code>hello.i</code>: 扩展了头文件的 C 代码 -<code>hello.s</code>：人类可读的汇编指令 -<code>hello.o</code>：机器代码（二进制对象） -<code>hello</code>：最终可执行文件</p><p>跑步：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./hello</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello, C!</span></span></code></pre></div><h4 id="步骤-2-预处理-include、-define、-if" tabindex="-1">步骤 2. 预处理（#include、#define、#if） <a class="header-anchor" href="#步骤-2-预处理-include、-define、-if" aria-label="Permalink to &quot;步骤 2. 预处理（#include、#define、#if）&quot;">​</a></h4><p>预处理器处理所有以<code>#</code>。它是纯文本的，还没有代码执行。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -E hello.c -o hello.i</span></span></code></pre></div><p>打开<code>hello.i</code>你会看到数千行<code>stdio.h</code>插入到您的代码中。它还替换了宏并删除了注释。</p><p>这是头文件、宏和条件编译发挥作用的阶段。</p><h4 id="步骤-3-编译-到汇编" tabindex="-1">步骤 3. 编译（到汇编） <a class="header-anchor" href="#步骤-3-编译-到汇编" aria-label="Permalink to &quot;步骤 3. 编译（到汇编）&quot;">​</a></h4><p>接下来，编译器将预处理的 C 代码转换为目标 CPU 的汇编语言。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -S hello.i -o hello.s</span></span></code></pre></div><p>打开<code>hello.s</code>查看低级指令，例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov     edi, OFFSET FLAT:.LC0</span></span>
<span class="line"><span>call    puts</span></span></code></pre></div><p>这些是特定于 CPU 的，在 x86、ARM 或 RISC-V 上，它们会有所不同。此阶段还执行优化、类型检查和错误检测。</p><h4 id="步骤-4-组装-到目标文件" tabindex="-1">步骤 4. 组装（到目标文件） <a class="header-anchor" href="#步骤-4-组装-到目标文件" aria-label="Permalink to &quot;步骤 4. 组装（到目标文件）&quot;">​</a></h4><p>汇编器将转换为<code>.s</code>文件转换为原始机器指令和数据结构，生成可重定位的目标文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c hello.s -o hello.o</span></span></code></pre></div><p>您可以使用以下方法检查它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>objdump -d hello.o</span></span></code></pre></div><p>代码中的每个函数都成为该目标文件中的一个符号。</p><h4 id="步骤-5-链接" tabindex="-1">步骤 5. 链接 <a class="header-anchor" href="#步骤-5-链接" aria-label="Permalink to &quot;步骤 5. 链接&quot;">​</a></h4><p>链接器（<code>ld</code>）将目标文件和库组合成一个可执行文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc hello.o -o hello</span></span></code></pre></div><p>如果您的程序使用外部函数（例如<code>printf</code>），链接器将它们定位在系统库中（例如，<code>/usr/lib/libc.so</code>）并记录他们的地址。</p><p>结果：一个独立的可执行文件可以运行。</p><h4 id="步骤-6-检查最终的二进制文件" tabindex="-1">步骤 6. 检查最终的二进制文件 <a class="header-anchor" href="#步骤-6-检查最终的二进制文件" aria-label="Permalink to &quot;步骤 6. 检查最终的二进制文件&quot;">​</a></h4><p>使用以下工具：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>file hello</span></span>
<span class="line"><span>nm hello | head</span></span>
<span class="line"><span>readelf -h hello</span></span></code></pre></div><p>这些揭示了：</p><ul><li>文件类型（ELF、Mach-O 等）</li><li>定义和未定义的符号</li><li>像这样的部分<code>.text</code>,<code>.data</code>,<code>.bss</code></li></ul><p>您现在可以看到机器级别的 C 代码。</p><h4 id="步骤-7-清理和自动化" tabindex="-1">步骤 7. 清理和自动化 <a class="header-anchor" href="#步骤-7-清理和自动化" aria-label="Permalink to &quot;步骤 7. 清理和自动化&quot;">​</a></h4><p>虽然手动运行每个步骤很有教育意义，但大多数时候您将依赖：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc hello.c -o hello</span></span></code></pre></div><p>或一个<code>Makefile</code>编排多个文件（我们将在第 55 节中介绍）。</p><h4 id="小代码-多文件示例" tabindex="-1">小代码：多文件示例 <a class="header-anchor" href="#小代码-多文件示例" aria-label="Permalink to &quot;小代码：多文件示例&quot;">​</a></h4><p>让我们手动构建一个两个文件的程序：</p><p>主程序</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;greet.h&quot;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    greet(&quot;C programmer&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>问候.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>void greet(const char *name) {</span></span>
<span class="line"><span>    printf(&quot;Hello, %s!\\n&quot;, name);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>问候.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void greet(const char *name);</span></span></code></pre></div><p>手动编译和链接：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c main.c</span></span>
<span class="line"><span>gcc -c greet.c</span></span>
<span class="line"><span>gcc main.o greet.o -o app</span></span>
<span class="line"><span>./app</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello, C programmer!</span></span></code></pre></div><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>了解编译管道可以帮助您：</p><ul><li>调试棘手的构建错误（<code>undefined reference</code>,<code>multiple definition</code>， ETC。）</li><li>控制优化和调试符号</li><li>检查中间阶段的学习或调整性能</li><li>构建您自己的轻量级构建系统或编译器</li></ul><p>这就是源代码如何一步一步、精确定义地变成机器现实的方式。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><p>1.生成所有中间文件（<code>.i</code>,<code>.s</code>,<code>.o</code>）一些程序并检查它们。 2. 尝试<code>gcc -O0</code>,<code>-O2</code>， 和<code>-O3</code>并观察装配如何变化。 3.添加<code>-g</code>并探索二进制文件<code>gdb</code>. 4. 构建一个跨多个领域的程序<code>.c</code>文件。 5. 使用<code>nm</code>和<code>objdump</code>追踪符号如何在各个阶段移动。</p><p>接下来，您将探索预处理器和宏、包含、常量和编译时代码生成背后的引擎。</p>`,71)])])}const g=a(p,[["render",o]]);export{u as __pageData,g as default};
